const TriangleHistogram& triangle_histogram_counts(const std::string&id,bool scale){
if(id=="L4E3G15")return scale?histogram_L4E3G15_triangle_child_scale:histogram_L4E3G15_triangle_child_pair;
if(id=="L4E3G366")return scale?histogram_L4E3G366_triangle_child_scale:histogram_L4E3G366_triangle_child_pair;
if(id=="L4E3G55")return scale?histogram_L4E3G55_triangle_child_scale:histogram_L4E3G55_triangle_child_pair;
if(id=="L4E3G68")return scale?histogram_L4E3G68_triangle_child_scale:histogram_L4E3G68_triangle_child_pair;
if(id=="L4E3G78")return scale?histogram_L4E3G78_triangle_child_scale:histogram_L4E3G78_triangle_child_pair;
if(id=="L4E3G98")return scale?histogram_L4E3G98_triangle_child_scale:histogram_L4E3G98_triangle_child_pair;
throw std::invalid_argument("untrained triangle child histogram");}

TriangleMappedPoint triangle_histogram_map(const std::string&id,bool scale,const std::array<Real,11>&p){
 const auto&model=triangle_histogram_counts(id,scale);TriangleMappedPoint out;out.jacobian=1;
 for(int axis=0;axis<11;++axis){long cumulative=0;bool found=false;
  for(int bin=0;bin<model.bins;++bin){long mass=model.counts[axis][bin];Real upper=Real(cumulative+mass)/65536;
   if(arb_lt(p[axis].v,upper.v)){Real slope=Real(65536)/Real(long(model.bins)*mass);out.point[axis]=Real(bin)/Real(model.bins)+(p[axis]-Real(cumulative)/65536)*slope;out.jacobian=out.jacobian*slope;found=true;break;}
   Real distance=p[axis]-upper;if(!arb_is_nonnegative(distance.v))throw std::runtime_error("uncertain exact histogram cell");cumulative+=mass;}
  if(!found)throw std::invalid_argument("strict triangle histogram cube required");pos(out.point[axis],"positive mapped coordinate");pos(1-out.point[axis],"mapped coordinate below one");}
 pos(out.jacobian,"positive complete histogram Jacobian");return out;
}
Real triangle_child_histogram_value(const TriangleTwoHostGraph&g,bool positive,bool scale,const std::array<Real,11>&p){
 auto m=triangle_histogram_map(g.id,scale,p);return m.jacobian*triangle_two_host_value(g,positive,scale,m.point);
}

